/* The model lives in the session's ACP config options, both in the
 * session/new result and in the reply to a change. One reader for both keeps
 * the shapes from drifting. */
#captureModels(result) {
  const options = Array.isArray(result?.configOptions) ? result.configOptions : [];
  const model = options.find((option) => option?.id === "model");
  if (!model || typeof model.currentValue !== "string" || !model.currentValue) return;
  this.models = {
    current: model.currentValue,
    options: (Array.isArray(model.options) ? model.options : [])
      .map((option) => option?.value)
      .filter((value) => typeof value === "string" && value),
  };
  this.listener({ type: "models", ...this.models });
}

/* Changes the model for the rest of the session. ACP applies this in place:
 * the session id does not change and its history is kept, which is what makes
 * switching mid-conversation safe. */
async selectModel(value) {
  if (typeof value !== "string" || !value) throw new TypeError("model required");
  this.#captureModels(await this.request("session/set_config_option", {
    sessionId: this.sessionId, configId: "model", value,
  }));
  return this.models;
}

