 * more would be dropped there anyway, and the device would report the list as
 * partial without knowing what it lost — so the cut is made here, where the
 * count that got left behind is still known. */
modelsSnapshot() {
  if (!this.linkActive || !this.nonce) return;
  const models = this.adapter.currentModels?.();
  if (!models?.current) return;
  try {
    const offered = models.options ?? [];
    let sent = offered.slice(0, MODEL_OPTIONS_CAP);
    let message = this.#modelsMessage(models.current, sent, sent.length < offered.length);
    /* Model names have no fixed length, so the cap alone cannot guarantee the
     * message fits. Shed from the end until it does. */
    while (sent.length > 0 && byteLength(message) > MAX_MESSAGE_BYTES) {
      sent = sent.slice(0, -1);
      message = this.#modelsMessage(models.current, sent, true);
    }
    this.publish(assertFits(message));
  } catch {
    // Display only: never let it interrupt permissions or liveness.
  }
}

