import test from "node:test";
import assert from "node:assert/strict";
import { DeskMateBridgeCore } from "../src/bridge-core.js";
import { FakeAcpAdapter } from "../src/fake-adapter.js";
import { byteLength, hello, MAX_MESSAGE_BYTES, promptSubmit } from "../src/protocol.js";

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((nextResolve, nextReject) => { resolve = nextResolve; reject = nextReject; });
  return { promise, resolve, reject };
}

const modelSelect = (nonce, epoch, model) => ({ v: 1, cmd: "model_select", connection_nonce: nonce, epoch, model });

test("models reach the device after the snapshot that locks the epoch", async () => {
  const outbound = [];
  const adapter = new FakeAcpAdapter();
  const core = new DeskMateBridgeCore({ adapter, publish: (message) => outbound.push(message) });
  adapter.offerModels("kiro/sonnet", ["kiro/sonnet", "kiro/haiku"]);

  await core.receive(hello("nonce"));

  const types = outbound.map((message) => message.type);
  const snapshotAt = types.indexOf("snapshot");
  const modelsAt = types.indexOf("models");
  assert.ok(snapshotAt >= 0 && modelsAt >= 0);
  /* The device locks its session epoch on the first snapshot and drops anything
   * epoch-stamped that arrives before it, so this order is a protocol
   * requirement rather than a cosmetic preference. */
  assert.ok(modelsAt > snapshotAt);

  const models = outbound.find((message) => message.type === "models");
  assert.equal(models.current, "kiro/sonnet");
  assert.deepEqual(models.options, ["kiro/sonnet", "kiro/haiku"]);
  assert.equal(models.truncated, false);
  assert.equal(models.connection_nonce, "nonce");
});

test("a bridge with no model to report stays silent instead of guessing", async () => {
  const outbound = [];
  const adapter = new FakeAcpAdapter();
  const core = new DeskMateBridgeCore({ adapter, publish: (message) => outbound.push(message) });

  await core.receive(hello("nonce"));

  assert.equal(outbound.some((message) => message.type === "models"), false);
});

test("device model_select asks the adapter and republishes what took effect", async () => {
  const outbound = [];
  const adapter = new FakeAcpAdapter();
  const core = new DeskMateBridgeCore({ adapter, publish: (message) => outbound.push(message) });
  adapter.offerModels("kiro/sonnet", ["kiro/sonnet", "mify/zhipuai/glm-5.3-flash"]);

  await core.receive(hello("nonce"));
  const epoch = outbound.find((message) => message.type === "snapshot").epoch;

  await core.receive(modelSelect("nonce", epoch, "mify/zhipuai/glm-5.3-flash"));

  assert.equal(adapter.currentModels().current, "mify/zhipuai/glm-5.3-flash");
  const models = outbound.filter((message) => message.type === "models");
  assert.equal(models.at(-1).current, "mify/zhipuai/glm-5.3-flash");
});

test("an unknown model is refused and the refusal is visible to the device", async () => {
  const outbound = [];
  const adapter = new FakeAcpAdapter();
  const core = new DeskMateBridgeCore({ adapter, publish: (message) => outbound.push(message) });
  adapter.offerModels("kiro/sonnet", ["kiro/sonnet"]);

  await core.receive(hello("nonce"));
  const epoch = outbound.find((message) => message.type === "snapshot").epoch;

  await core.receive(modelSelect("nonce", epoch, "kiro/does-not-exist"));

  assert.equal(adapter.currentModels().current, "kiro/sonnet");
  /* Reported rather than dropped: silence would be indistinguishable from a lost
   * message at the device. */
  assert.equal(outbound.at(-1).msg, "Model change refused");
});

test("a running turn keeps its model, including a turn the device never saw", async () => {
  const outbound = [];
  const adapter = new FakeAcpAdapter();
  const pending = deferred();
  adapter.submitHandler = () => pending.promise;
  const core = new DeskMateBridgeCore({ adapter, publish: (message) => outbound.push(message) });
  adapter.offerModels("kiro/sonnet", ["kiro/sonnet", "kiro/haiku"]);

  await core.receive(hello("nonce"));
  const epoch = outbound.find((message) => message.type === "snapshot").epoch;

  /* Started locally, at the bridge's own prompt, so the device's turn check
   * cannot know about it. This side has to refuse on its own. */
  const local = core.submitLocal("a local turn");
  await core.receive(modelSelect("nonce", epoch, "kiro/haiku"));

  assert.equal(adapter.currentModels().current, "kiro/sonnet");
  assert.equal(outbound.at(-1).msg, "Model unchanged: a turn is running");

  pending.resolve({ stopReason: "end_turn" });
  await local;

  /* Once the turn is done the same request is honoured. */
  await core.receive(modelSelect("nonce", epoch, "kiro/haiku"));
  assert.equal(adapter.currentModels().current, "kiro/haiku");
});

test("stale nonce or epoch cannot change the model", async () => {
  const outbound = [];
  const adapter = new FakeAcpAdapter();
  const core = new DeskMateBridgeCore({ adapter, publish: (message) => outbound.push(message) });
  adapter.offerModels("kiro/sonnet", ["kiro/sonnet", "kiro/haiku"]);

  await core.receive(hello("nonce"));
  const epoch = outbound.find((message) => message.type === "snapshot").epoch;

  await core.receive(modelSelect("wrong-nonce", epoch, "kiro/haiku"));
  await core.receive(modelSelect("nonce", "wrong-epoch", "kiro/haiku"));
  await core.receive(modelSelect("nonce", epoch, ""));

  assert.equal(adapter.currentModels().current, "kiro/sonnet");
});

test("more models than the device holds are cut here, and the cut is declared", async () => {
  const outbound = [];
  const adapter = new FakeAcpAdapter();
  const core = new DeskMateBridgeCore({ adapter, publish: (message) => outbound.push(message) });
  const offered = Array.from({ length: 40 }, (_unused, index) => `kiro/model-${index}`);
  adapter.offerModels(offered[0], offered);

  await core.receive(hello("nonce"));

  const models = outbound.find((message) => message.type === "models");
  /* Cut on this side, where the number left behind is still known: the device
   * would otherwise have to report a partial list without knowing it was one. */
  assert.equal(models.options.length, 32);
  assert.equal(models.truncated, true);
  assert.deepEqual(models.options, offered.slice(0, 32));
});

test("long model names shed until the message fits the link", async () => {
  const outbound = [];
  const adapter = new FakeAcpAdapter();
  const core = new DeskMateBridgeCore({ adapter, publish: (message) => outbound.push(message) });
  /* Thirty-two of these blow the 4 KiB cap, so the option cap alone is not
   * enough — names have no fixed length. */
  const offered = Array.from({ length: 32 }, (_unused, index) => `kiro/${"n".repeat(200)}-${index}`);
  adapter.offerModels(offered[0], offered);

  await core.receive(hello("nonce"));

  const models = outbound.find((message) => message.type === "models");
  assert.ok(models, "a models message is still published");
  assert.ok(models.options.length < 32);
  assert.ok(models.options.length > 0);
  assert.equal(models.truncated, true);
  assert.ok(byteLength(models) <= MAX_MESSAGE_BYTES);
});

test("a model switch made on the PC side is pushed to the device", async () => {
  const outbound = [];
  const adapter = new FakeAcpAdapter();
  const core = new DeskMateBridgeCore({ adapter, publish: (message) => outbound.push(message) });
  adapter.offerModels("kiro/sonnet", ["kiro/sonnet", "kiro/haiku"]);

  await core.receive(hello("nonce"));
  const before = outbound.filter((message) => message.type === "models").length;

  /* Switched through the adapter, as the attach window does — no device request
   * involved. The device still has to learn about it. */
  await adapter.selectModel("kiro/haiku");

  const models = outbound.filter((message) => message.type === "models");
  assert.equal(models.length, before + 1);
  assert.equal(models.at(-1).current, "kiro/haiku");
});

test("models are not published to a device that has gone away", async () => {
